(function(){
  function parseFields(s){
    var idx={}, parts=String(s).split(',');
    for(var i=0;i<parts.length;i++){ var p=parts[i].trim(); if(!p)continue;
      if(p.indexOf('-')>=0){ var a=p.split('-'); var lo=+a[0],hi=+a[1]; if(isNaN(lo)||isNaN(hi))return null;
        for(var j=lo;j<=hi;j++) idx[j]=1; } else { var n=+p; if(isNaN(n))return null; idx[n]=1; } }
    return idx;
  }
  function pick(text,fields,delim){
    text=String(text==null?'':text); delim=delim||',';
    var idx=parseFields(fields); if(!idx) return {error:'字段格式非法'};
    var lines=text.split(/\r\n|\r|\n/).filter(function(l){return l!=='';});
    var out=lines.map(function(l){ var cols=l.split(delim);
      return Object.keys(idx).sort(function(a,b){return a-b;}).map(function(k){ return cols[k-1]===undefined?'':cols[k-1]; }).join(delim); });
    return {value:out.join('\n')};
  }
  var API={pick:pick,parseFields:parseFields};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__ChooseForge__=API;
})();
